const entrada = $input.first().json;
const p = (entrada && entrada.body && typeof entrada.body === 'object') ? entrada.body : entrada;

const esc = (v) => String(v === null || v === undefined ? '' : v)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

const txt = (v, alt) => {
  const s = String(v === null || v === undefined ? '' : v).trim();
  return s.length ? s : (alt || '-');
};

// La confianza llega como fracción (0.62) desde SIGAD; se muestra en porcentaje (62).
let confianza = Number(p.confianza);
if (!isFinite(confianza)) {
  const score = Number(p.score);
  confianza = isFinite(score) ? score : 0;
}
const pct = Math.max(0, Math.min(100, Math.round(confianza > 0 && confianza <= 1 ? confianza * 100 : confianza)));
const pctTexto = String(pct);
const bajoUmbral = pct < 70;

const documento = txt(p.documento || p.nombre || p.titulo, 'Documento sin nombre');
const resumen = txt(p.resumen, 'Sin resumen generado por el motor de IA.');
const decision = txt(p.decision);
const estado = txt(p.estado);
const urlRevision = txt(p.url_revision || p.urlRevision);
const esApertura = String(p.evento || '') === 'revision_abierta';

const categoriaSugerida = esApertura
  ? txt(p.categoria_sugerida || p.categoria)
  : txt(p.categoria_final || p.categoria_sugerida || p.categoria);

const ACENTO = bajoUmbral ? '#d97706' : '#059669';
const BARRA_BG = '#e5e7eb';
const COLOR_ESTADO = { procesado: '#059669', rechazado: '#b91c1c' }[estado] || '#111827';
const BADGE = {
  APROBAR: ['#065f46', '#d1fae5'],
  CORREGIR: ['#1e40af', '#dbeafe'],
  RECHAZAR: ['#991b1b', '#fee2e2'],
};
const badgeDecision = (() => {
  if (!decision) return '-';
  const b = BADGE[String(decision).toUpperCase()] || ['#374151', '#f3f4f6'];
  return '<span style="display:inline-block;padding:3px 12px;border-radius:999px;background:' + b[1] + ';color:' + b[0] + ';font-weight:700;font-size:13px;letter-spacing:.3px;">' + esc(decision) + '</span>';
})();

const th = (e) => '<td width="34%" style="padding:11px 16px;background:#f9fafb;color:#6b7280;font-size:13px;font-weight:600;border-bottom:1px solid #e5e7eb;">' + e + '</td>';
const td = (v) => '<td style="padding:11px 16px;color:#111827;font-size:14px;border-bottom:1px solid #e5e7eb;">' + v + '</td>';
const fila = (etiqueta, valor) => '<tr>' + th(etiqueta) + td(valor) + '</tr>';
const tabla = (filas) => '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #e5e7eb;">' + filas + '</table>';

const cabecera = (color, titulo, sub) =>
  '<div style="background:' + color + ';padding:22px 24px;">'
  + '<div style="color:#ffffff;font-size:11px;letter-spacing:1.4px;text-transform:uppercase;opacity:.85;font-weight:600;">SIGAD &middot; Gesti&oacute;n Documental IA</div>'
  + '<div style="color:#ffffff;font-size:23px;font-weight:700;margin-top:6px;line-height:1.3;">' + titulo + '</div>'
  + '<div style="color:#ffffff;font-size:13px;margin-top:5px;opacity:.92;">' + sub + '</div>'
  + '</div>';

const barra = (etiqueta, nota) =>
  '<div style="margin:20px 0 2px;">'
  + '<div style="font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.7px;font-weight:600;margin-bottom:8px;">' + etiqueta + '</div>'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;"><tr>'
  + '<td width="' + pctTexto + '%" style="background:' + ACENTO + ';height:9px;font-size:0;line-height:0;">&nbsp;</td>'
  + '<td style="background:' + BARRA_BG + ';height:9px;font-size:0;line-height:0;">&nbsp;</td>'
  + '</tr></table>'
  + '<div style="font-size:13px;color:#4b5563;margin-top:9px;"><strong style="color:#111827;font-size:15px;">' + pctTexto + '%</strong> &mdash; ' + nota + '</div>'
  + '</div>';

const bloqueResumen =
  '<div style="margin-top:22px;padding:14px 16px;background:#f9fafb;border-left:4px solid ' + ACENTO + ';border-radius:4px;">'
  + '<div style="font-size:11px;color:#6b7280;text-transform:uppercase;letter-spacing:.7px;font-weight:600;">Resumen IA</div>'
  + '<div style="margin-top:7px;color:#111827;font-size:14px;line-height:1.65;">' + esc(resumen).replace(/\r?\n/g, '<br>') + '</div>'
  + '</div>';

const boton = (url, etiqueta, bg) => url
  ? '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;"><tr><td style="padding:24px 0 4px;text-align:center;">'
    + '<a href="' + esc(url) + '" style="background:' + bg + ';color:#ffffff;text-decoration:none;padding:14px 28px;border-radius:8px;font-weight:700;font-size:15px;display:inline-block;">' + etiqueta + '</a>'
    + '<div style="padding-top:10px;color:#9ca3af;font-size:11px;">' + esc(url) + '</div>'
    + '</td></tr></table>'
  : '';

const pie =
  '<div style="background:#f9fafb;border-top:1px solid #e5e7eb;padding:16px 24px;">'
  + '<p style="margin:0;color:#9ca3af;font-size:11px;line-height:1.6;">Notificaci&oacute;n autom&aacute;tica generada por <strong style="color:#6b7280;">SIGAD</strong> &middot; Desarrollo de Aplicaciones Empresariales &middot; UTS.<br>Este correo no es monitoreado; no lo respondas.</p>'
  + '</div>';

const shell = (contenido) =>
  '<div style="margin:0;padding:26px 14px;background:#f3f4f6;font-family:Segoe UI,Roboto,Helvetica,Arial,sans-serif;">'
  + '<div style="max-width:600px;margin:0 auto;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;">'
  + contenido + pie
  + '</div></div>';

const htmlApertura = shell(
  cabecera('#b45309', 'Revisi&oacute;n pendiente', 'El documento necesita una decisi&oacute;n humana')
  + '<div style="padding:26px 24px;">'
  + '<p style="margin:0 0 18px;color:#374151;font-size:15px;line-height:1.65;">El motor de IA <strong>no alcanz&oacute; el umbral de confianza del 70%</strong>, por lo que el documento qued&oacute; en estado <strong>requiere revisi&oacute;n</strong>. Ingresa a SIGAD para aprobarlo, corregirlo o rechazarlo.</p>'
  + tabla(
    fila('Documento', '<strong>' + esc(documento) + '</strong>')
    + fila('Categor&iacute;a sugerida', esc(categoriaSugerida))
  )
  + barra('Confianza de la clasificaci&oacute;n', 'por debajo del umbral requerido (70%)')
  + bloqueResumen
  + boton(urlRevision, 'Revisar documento en SIGAD', '#2563eb')
  + '</div>'
);

const htmlCierre = shell(
  cabecera('#047857', 'Revisi&oacute;n cerrada', 'La revisi&oacute;n del documento fue atendida')
  + '<div style="padding:26px 24px;">'
  + '<p style="margin:0 0 18px;color:#374151;font-size:15px;line-height:1.65;">La revisi&oacute;n fue completada y el documento qued&oacute; con el siguiente resultado:</p>'
  + tabla(
    fila('Documento', '<strong>' + esc(documento) + '</strong>')
    + fila('Decisi&oacute;n', badgeDecision)
    + fila('Estado final', '<strong style="color:' + COLOR_ESTADO + ';">' + esc(estado) + '</strong>')
    + fila('Categor&iacute;a final', esc(categoriaSugerida))
  )
  + '<div style="margin-top:22px;padding:14px 16px;background:#ecfdf5;border-left:4px solid #10b981;border-radius:4px;color:#065f46;font-size:14px;line-height:1.6;">'
  + 'El documento ya no est&aacute; pendiente de revisi&oacute;n y fue incorporado al cat&aacute;logo con la categor&iacute;a final indicada.'
  + '</div>'
  + boton(urlRevision, 'Ver documento en SIGAD', '#047857')
  + '</div>'
);

const textoApertura = 'SIGAD \u00b7 Revisi\u00f3n pendiente\n\n'
  + 'El motor de IA de SIGAD no alcanz\u00f3 el umbral de confianza (70%) y el documento necesita tu decisi\u00f3n.\n\n'
  + 'Documento: ' + documento + '\n'
  + 'Categor\u00eda sugerida: ' + categoriaSugerida + '\n'
  + 'Confianza: ' + pctTexto + '% (umbral 70%)\n\n'
  + 'Resumen IA:\n' + resumen + '\n\n'
  + (urlRevision ? 'Revisar en: ' + urlRevision : 'Abre SIGAD para aprobar, corregir o rechazar el documento.');

const textoCierre = 'SIGAD \u00b7 Revisi\u00f3n cerrada\n\n'
  + 'La revisi\u00f3n del documento fue atendida.\n\n'
  + 'Documento: ' + documento + '\n'
  + 'Decisi\u00f3n: ' + decision + '\n'
  + 'Estado final: ' + estado + '\n'
  + 'Categor\u00eda final: ' + categoriaSugerida + '\n\n'
  + 'El documento ya no est\u00e1 pendiente de revisi\u00f3n.';

return [{
  json: {
    ...p,
    evento: p.evento,
    documento_id: p.documento_id,
    documento,
    confianza_ia: Number(confianza),
    confianza_pct: pct,
    categoria_sugerida: categoriaSugerida,
    url_revision: urlRevision,
    asunto_apertura: '[SIGAD] Revisi\u00f3n pendiente: ' + documento + ' (' + pctTexto + '% confianza)',
    cuerpo_apertura: textoApertura,
    cuerpo_apertura_html: htmlApertura,
    asunto_cierre: '[SIGAD] Revisi\u00f3n cerrada: ' + documento,
    cuerpo_cierre: textoCierre,
    cuerpo_cierre_html: htmlCierre
  }
}];

